        ($results | Where-Object Status -eq 'passed').Count  | Should -Be 1
        ($results | Where-Object Status -eq 'failed').Count  | Should -Be 1
        ($results | Where-Object Status -eq 'skipped').Count | Should -Be 1
    }
}

